<script setup lang="ts">import{onMounted,reactive,ref}from"vue";import{createBatch,listBatches,listCompetitions,type Batch,type Competition}from"@/api/business";const rows=ref<Batch[]>([]),cs=ref<Competition[]>([]),dialog=ref(false);const form=reactive({name:"",competition:undefined as number|undefined});async function load(){[rows.value,cs.value]=await Promise.all([listBatches(),listCompetitions()])}async function submit(){await createBatch(form);dialog.value=false;await load()}onMounted(load);</script>
<template><div class="page"><header><div><h2>名单与批次</h2><p>导入获奖名单、检查版本并提交会签</p></div><div><el-button tag="a" href="/api/v1/excel/template/">下载 Excel 模板</el-button><el-button type="primary" @click="dialog=true">新建批次</el-button></div></header><el-table :data="rows" border><el-table-column prop="name" label="批次"/><el-table-column prop="competition_name" label="竞赛"/><el-table-column prop="current_version" label="版本"/><el-table-column prop="status" label="状态"/></el-table><el-dialog v-model="dialog" title="新建批次"><el-form label-position="top"><el-form-item label="批次名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="竞赛"><el-select v-model="form.competition"><el-option v-for="c in cs" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item></el-form><template #footer><el-button type="primary" @click="submit">创建</el-button></template></el-dialog></div></template><style scoped>.page{padding:20px}header{display:flex;justify-content:space-between;margin-bottom:18px}h2{margin:0;font-size:20px;letter-spacing:0}p{color:#73767a}</style>
